package com.hbm.machine.radar;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.BlockHitResult;
public final class LargeRadarBlock extends DummyableBlock{public LargeRadarBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return simpleCodec(p->new LargeRadarBlock());}@Override public int[] dimensions(){return new int[]{4,0,1,1,1,1};}@Override public int offset(){return 1;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return isCore(s)?new RadarBlockEntity(p,s,true):isPort(s)?new RadarPort(p,s):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> type){return isCore(s)?createTickerHelper(type,RadarContent.LARGE_ENTITY.get(),RadarBlockEntity::tick):null;}@Override public void setPlacedBy(Level level,BlockPos p,BlockState s,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,p,s,placer,stack);if(level.isClientSide)return;var core=p.relative(placementFacing(s),-offset());for(var port:RadarBlockEntity.ports(core,true))setPort(level,port,true);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){return RadarBlock.activate(l,p,findCore(l,p),player);}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction side){return s.getValue(LEGACY_META)>=6&&l.getBlockEntity(p.relative(side)) instanceof RadarBlockEntity radar?radar.redPower():0;}@Override protected int getDirectSignal(BlockState s,BlockGetter l,BlockPos p,Direction side){return getSignal(s,l,p,side);}}
